; fill.asm -- chapter 12: a routine that calls itself
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "fill.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
MAP     EQU $C400               ; the screen's 768 cells, a copy in the RAM
BLOCK   EQU 128                 ; black
WALL    EQU 129                 ; a wall
; A routine that calls itself: the white cells inside a ring of
; walls blackened, starting from column 6, row 11.
; The map is a copy of the screen in the RAM, sent to the VDP at the end. The
; 2048 bytes below SYS_AREA are painted $E5 first, so that the bytes the
; stack changed show how deep it went.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0400        ; character 128: every pixel ink
        ld hl, full
        ld b, 8
ch128:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz ch128
        VRAM_WRITE $0408        ; character 129: a fine chequer
        ld hl, check
        ld b, 8
ch129:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz ch129
        ld hl, MAP
        ld de, MAP + 1
        ld (hl), ' '
        ld bc, 768 - 1
        ldir                    ; the map all white
        ld hl, walls            ; the walls: 104 cells
        ld b, 104
dw1:    push bc
        ld d, (hl)              ; the column
        inc hl
        ld e, (hl)              ; the row
        inc hl
        push hl
        call cell
        ld (hl), WALL           ; a wall in the map
        pop hl
        pop bc
        djnz dw1
        ld hl, $EB80
        ld de, $EB81
        ld (hl), $E5
        ld bc, 2048 - 1
        ldir                    ; the stack's memory painted
        ld d, 6                 ; the column
        ld e, 11                ; the row
        call fill
filled: VRAM_WRITE $1800        ; the map into the name table
        ld hl, MAP
        ld bc, 768
put:    ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, put
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; fill: D = column, E = row. Blackens the cell if it is white, and then,
;       calling itself, every white cell joined to it. Keeps DE; uses A, HL.
fill:   ld a, d
        cp 32
        ret nc                  ; off the screen to the side (-1 is 255)
        ld a, e
        cp 24
        ret nc                  ; off the top or the bottom
        call cell               ; HL: the cell in the map
        ld a, (hl)
        cp ' '
        ret nz                  ; a wall, or black already
        ld (hl), BLOCK          ; black
        inc d
        call fill               ; the cell to the right
        dec d
        dec d
        call fill               ; to the left
        inc d
        inc e
        call fill               ; below
        dec e
        dec e
        call fill               ; above
        inc e
        ret

; cell: HL = the cell of the map at column D, row E. Uses A.
cell:   ld l, e
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; the row times 32
        ld a, l
        or d                    ; plus the column
        ld l, a
        ld a, h
        or high MAP             ; plus $C400
        ld h, a
        ret

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
full:   db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
check:  db $AA, $55, $AA, $55, $AA, $55, $AA, $55
walls:
        db 12, 1, 13, 1, 14, 1, 15, 1, 16, 1, 17, 1, 18, 1, 19, 1
        db 10, 2, 11, 2, 12, 2, 19, 2, 20, 2, 21, 2, 8, 3, 9, 3
        db 10, 3, 21, 3, 22, 3, 23, 3, 7, 4, 8, 4, 23, 4, 24, 4
        db 7, 5, 24, 5, 6, 6, 7, 6, 24, 6, 25, 6, 6, 7, 25, 7
        db 5, 8, 6, 8, 25, 8, 26, 8, 5, 9, 13, 9, 14, 9, 15, 9
        db 16, 9, 17, 9, 18, 9, 26, 9, 5, 10, 13, 10, 18, 10, 26, 10
        db 5, 11, 13, 11, 18, 11, 26, 11, 5, 12, 13, 12, 18, 12, 26, 12
        db 5, 13, 13, 13, 18, 13, 26, 13, 5, 14, 13, 14, 14, 14, 15, 14
        db 16, 14, 17, 14, 18, 14, 26, 14, 5, 15, 6, 15, 25, 15, 26, 15
        db 6, 16, 25, 16, 6, 17, 7, 17, 24, 17, 25, 17, 7, 18, 24, 18
        db 7, 19, 8, 19, 23, 19, 24, 19, 8, 20, 9, 20, 10, 20, 21, 20
        db 22, 20, 23, 20, 10, 21, 11, 21, 12, 21, 19, 21, 20, 21, 21, 21
        db 12, 22, 13, 22, 14, 22, 15, 22, 16, 22, 17, 22, 18, 22, 19, 22
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
